import {prepareCanvas,renderSlime,renderNinja,renderDentist,TASK_ICONS} from './touch-render.js';
export const TOUCH_WORLDS={slime:{name:'Slime Lab',icon:'🧪',tag:'STRETCH. SQUISH. SOAR.',headline:'A little slime.<br>A lot of possibility.',intro:'Touch the slime to grab its body. Two fingers stretch or squeeze it. Pull backward and let go to fling. Collect the gold orbs and reach the exit. Later levels add splitting: power both pads, merge, then escape.',features:'30 COURSES · LIVE SOFT-BODY PHYSICS · 4 THEMES',looks:[['mint','Mint Smile',0],['berry','Berry Freckles',3],['solar','Solar Crown',10],['cosmic','Cosmic Spark',20]]},dentist:{name:'Monster Dentist',icon:'🦷',tag:'SMALL TOOLS. ENORMOUS SMILES.',headline:'Open wide.<br>Make a monster smile.',intro:'Read the icons under each tooth and choose the matching tool. Scrub dirt, spray plaque, trace around food, fill cavities, and pull loose teeth along their arrows. Drag replacement teeth from the tray and rotate them to match. These monsters are silly, friendly and very ticklish.',features:'7 ORIGINAL PATIENTS · 8 REAL TOOLS · 30 CLINIC CASES'},ninja:{name:'Shadow Ninjas',icon:'🥷',tag:'PLAN THE PATH. OWN THE SHADOWS.',headline:'Quiet steps.<br>Brilliant escapes.',intro:'Draw a route or swipe in Dash mode. Hold Shield with another finger while moving. Throw a star at the gold switch to open its door. Collect gold scrolls, activate pressure pads where shown, and reach the exit. Hide behind green cover to break sight and recharge.',features:'30 MISSIONS · PATROLS & LASERS · GESTURE MOVEMENT',looks:[['moon','Moon Scarf',0],['bamboo','Bamboo Scout',3],['comet','Comet Trail',10],['neon','Neon Dragon',20]]}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seconds=t=>(t/1000).toFixed(1)+'s';
const tools={ninja:[['path','〰','Draw route'],['dash','➤','Swipe dash'],['star','✦','Throw star'],['slide','⇢','Slide'],['jump','↗','Wall jump'],['blink','◈','Blink']],slime:[]};
export function completedTouchLevels(p,game){const set=new Set();for(const r of p.results.filter(r=>r.game===game&&r.ruleset===(game==='slime'?'slime-sling-v2':'touch-v1')))for(const d of r.details?.rounds||[r.details])if(d?.completed)set.add(r.levelId);return set.size;}
export function openTouchWorld(host,{game,exit,notify,ask,initialPage='setup'}){
 const spec=TOUCH_WORLDS[game],dentist=game==='dentist',$=s=>host.querySelector(s);let difficulty=3,level=13,versus=false,series=3,ids=[DB.active,DB.profiles.find(p=>p.id!==DB.active)?.id],phase='setup',page='setup',disposed=false,paused=false,models=[],turn=0,starter=0,round=0,wins=[0,0],rounds=[],committed=false,last=0,raf=0,recordInfo=[],countdown=0,skins=['mint','mint'],notices=[0,0];
 host.innerHTML=`<section class="new-arcade touch-room touch-${game}"><header class="new-header"><button class="btn secondary" id="touchExit">⌂ ARCADE</button><div><span class="eyebrow">NEON ARCADE UNIVERSE</span><h1>${spec.icon} ${spec.name}</h1></div><nav><button class="btn secondary" id="touchSetup">SETUP</button><button class="btn secondary" id="touchRecords">♛ RECORDS</button><button class="icon-btn" id="touchMute" aria-label="Mute sound">♪</button><button class="icon-btn" id="touchFull" aria-label="Fullscreen">⛶</button></nav></header><div id="touchContent"></div></section>`;
 const content=$('#touchContent'),observer=new ResizeObserver(()=>resize());$('#touchFull').onclick=()=>document.getElementById('fullscreen')?.click();$('#touchMute').onclick=()=>{document.getElementById('mute')?.click();$('#touchMute').textContent=DB.settings.muted?'♪̸':'♪';};
 async function leave(action){if(page==='play'&&['play','countdown','handoff'].includes(phase)){pause(true);if(!await ask('Leave this challenge?','This unfinished match will not change records, wins or achievements.')){pause(false);return;}}action();}
 $('#touchExit').onclick=()=>leave(exit);$('#touchSetup').onclick=()=>leave(setup);$('#touchRecords').onclick=()=>leave(records);
 function profileOptions(selected){return DB.profiles.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('');}
 function chosenLook(i){const p=player(ids[i]),defaultSkin=spec.looks?.[0]?.[0]||'mint',saved=p.touchLooks?.[game],eligible=spec.looks?.filter(l=>completedTouchLevels(p,game)>=l[2])||[];return eligible.some(l=>l[0]===saved)?saved:defaultSkin;}
 const gate=createInstructionGate({game:game,onBack:exit});
 function requestSession(){gate.show({players:(versus?ids:ids.slice(0,1)).map(id=>player(id).name),difficulty:LEVELS[difficulty-1]},()=>startRound(true));}
 function setup(){phase='setup';page='setup';paused=false;models=[];observer.disconnect();content.innerHTML=`<div class="new-setup touch-setup"><section class="new-intro"><span class="eyebrow">${spec.tag}</span><h2>${spec.headline.replace('<br>','<br><em>')+'</em>'}</h2><div class="touch-poster poster-${game}">${poster(game)}</div><p>${spec.intro}</p><div class="touch-featureline">${spec.features}</div></section><section class="panel new-options"><div class="mode-toggle"><button data-touch-count="1" class="${!versus?'selected':''}">☺ 1 Player</button><button data-touch-count="2" class="${versus?'selected':''}" ${DB.profiles.length<2?'disabled':''}>⚔ 2 Players</button></div><div class="form-columns"><label>Player 1<select id="touchP1">${profileOptions(ids[0])}</select></label>${versus?`<label>Player 2<select id="touchP2">${profileOptions(ids[1])}</select></label>`:''}</div>${versus?`<label>Match length<select id="touchSeries">${[1,3,5].map(n=>`<option value="${n}" ${series===n?'selected':''}>${n===1?'Single round':'Best of '+n}</option>`).join('')}</select></label>`:''}<label>DIFFICULTY <b>${LEVELS[difficulty-1]}</b><input id="touchDifficulty" type="range" min="1" max="5" value="${difficulty}" aria-label="Difficulty"></label><button class="btn secondary" id="touchLevels">▦ ${dentist?'CASE':'LEVEL'} ${level} · ${levelName(level)}</button>${spec.looks?(versus?ids:ids.slice(0,1)).map((id,i)=>{const p=player(id),completed=completedTouchLevels(p,game);return `<label>${esc(p.name)}’s look · ${completed} levels completed<select data-touch-look="${i}">${spec.looks.map(([key,name,min])=>`<option value="${key}" ${chosenLook(i)===key?'selected':''} ${completed<min?'disabled':''}>${name}${completed<min?' · '+min+' levels':''}</option>`).join('')}</select></label>`;}).join(''):''}<div class="intro-fairness">${versus?dentist?'Alternating turns · identical patient · accuracy, then time':'Simultaneous race · independent touch zones · identical course':dentist?'Active-treatment clock · no reaction-time scores':'Collect the required items · finish for stars and cosmetics'}</div><button class="btn primary full" id="touchLaunch">${versus?'START THE MATCH ⚔':'LET’S PLAY →'}</button></section></div>`;
 content.querySelectorAll('[data-touch-count]').forEach(b=>b.onclick=()=>{versus=b.dataset.touchCount==='2';setup();});$('#touchP1').onchange=e=>{ids[0]=e.target.value;setup();};if($('#touchP2'))$('#touchP2').onchange=e=>{ids[1]=e.target.value;setup();};if($('#touchSeries'))$('#touchSeries').onchange=e=>series=+e.target.value;$('#touchDifficulty').oninput=e=>{difficulty=+e.target.value;level=(difficulty-1)*6+1;e.target.previousElementSibling.textContent=LEVELS[difficulty-1];};$('#touchDifficulty').onchange=setup;$('#touchLevels').onclick=levels;
 content.querySelectorAll('[data-touch-look]').forEach(s=>s.onchange=()=>{const p=player(ids[+s.dataset.touchLook]);p.touchLooks??={};p.touchLooks[game]=s.value;save();});
 $('#touchLaunch').onclick=()=>{ids[0]=$('#touchP1').value;if(versus){ids[1]=$('#touchP2').value;if(ids[0]===ids[1]){notify('Pick two different player profiles.');return;}}DB.active=ids[0];save();round=0;wins=[0,0];rounds=[];committed=false;requestSession();};
 }
 function levelName(id){return game==='slime'?SLIME_LEVELS[id-1].name:game==='ninja'?NINJA_LEVELS[id-1].name:PATIENTS[(id-1)%7].name;}
 function levels(){page='levels';phase='setup';content.innerHTML=`<div class="new-levels"><div class="page-heading"><div><span class="eyebrow">${spec.name.toUpperCase()}</span><h2>${dentist?'Pick a patient.':'Choose your next adventure.'}</h2><p>Six challenges per tier. All 30 are playable; your stars and best times stay with your profile.</p></div><button class="btn secondary" id="touchLevelBack">← SETUP</button></div>${LEVELS.map((d,i)=>`<h3>${d}</h3><div class="circuit-level-grid">${Array.from({length:6},(_,j)=>i*6+j+1).map(id=>{const records=player(ids[0]).results.filter(r=>r.game===game&&r.levelId===game+'-'+id&&r.mode==='solo'),rounds=records.flatMap(r=>r.details?.rounds||[r.details]).filter(Boolean),stars=Math.max(0,...rounds.map(d=>d.stars||0));return `<button data-touch-level="${id}" class="${id===level?'selected':''}"><b>${id}</b><span>${levelName(id)}</span><small>${stars?'★'.repeat(stars):dentist?'CLINIC CASE':'READY TO EXPLORE'}</small></button>`;}).join('')}</div>`).join('')}</div>`;$('#touchLevelBack').onclick=setup;content.querySelectorAll('[data-touch-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.touchLevel;difficulty=Math.floor((level-1)/6)+1;setup();});}
 function createModel(){return new({slime:SlimeModel,ninja:NinjaModel,dentist:DentistModel}[game])({level,difficulty});}
 function startRound(acknowledged=false){round++;phase='ready';page='play';paused=false;turn=dentist&&versus?(starter+round-1)%2:0;models=(versus?ids:ids.slice(0,1)).map(()=>createModel());skins=(versus?ids:ids.slice(0,1)).map((_,i)=>chosenLook(i));notices=[0,0];buildPlay();if(dentist&&versus&&acknowledged!==true)showReady();else beginPlaying();last=performance.now();}
 function activeIndexes(){return dentist?[turn]:models.map((_,i)=>i);}
 function buildPlay(){const shown=activeIndexes();content.innerHTML=`<div class="new-play touch-play"><div class="new-matchbar"><span>${LEVELS[difficulty-1]} · ${dentist?'CASE':'LEVEL'} ${level} · ${levelName(level)}${versus?' · ROUND '+round+' · '+wins.join(' : '):''}</span><div><button class="btn secondary" id="touchPause">Ⅱ PAUSE</button><button class="btn secondary" id="touchRestart">↻ RESTART</button></div></div><div class="new-playfield ${shown.length===2?'circuit-split':''}">${shown.map(i=>`<section class="new-zone touch-zone" style="--player:${player(ids[i]).color}" data-touch-zone="${i}"><div class="new-hud" data-touch-hud="${i}"></div>${dentist?`<div class="dental-checklist" data-dental-checklist="${i}"></div>`:''}<div class="new-canvas-wrap"><canvas data-touch-canvas="${i}" aria-label="${esc(player(ids[i]).name)} ${spec.name} touch play area"></canvas></div><div class="touch-toolrow" data-touch-tools="${i}">${controlHTML(i)}</div><div class="new-help" data-touch-help="${i}"></div></section>`).join('')}</div><div class="new-overlay" id="touchOverlay" hidden></div></div>`;
 $('#touchPause').onclick=()=>pause(!paused);$('#touchRestart').onclick=async()=>{pause(true);if(await ask('Restart this match?','Unfinished scores will be discarded. Previous records stay saved.')){round=0;rounds=[];wins=[0,0];committed=false;startRound(true);}else pause(false);};
 for(const i of shown){const c=$(`[data-touch-canvas="${i}"]`);bindCanvas(c,i);bindTools(i);}
 observer.disconnect();content.querySelectorAll('canvas').forEach(c=>observer.observe(c));resize();
 }
 function controlHTML(i){const m=models[i];if(game==='slime')return `<button class="btn accent" data-slime-split="${i}" ${!m.level.split?'disabled':''}>◉ SPLIT</button><button class="btn secondary" data-slime-reset="${i}">↺ RESET SLIME</button><span class="touch-toolhint">2 fingers: stretch / pinch<br>Pull back, release: fling</span>`;
 if(dentist)return DENTAL_TOOLS.map(t=>`<button class="touch-tool ${m.tool===t.id?'selected':''}" data-dental-tool="${t.id}" data-owner="${i}"><b>${t.icon}</b><span>${t.name}</span></button>`).join('')+`<button class="touch-tool" data-tooth-rotate="${i}"><b>⟳</b><span>Rotate tooth</span></button>`;
 return tools.ninja.map(([key,icon,title])=>`<button class="touch-tool ${m.mode===key?'selected':''}" data-ninja-mode="${key}" data-owner="${i}"><b>${icon}</b><span>${title}</span></button>`).join('')+`<button class="touch-tool shield-tool" data-shield="${i}"><b>◌</b><span>HOLD SHIELD</span></button><button class="touch-tool" data-route-cancel="${i}"><b>✕</b><span>Cancel route</span></button>`;
 }
 function bindTools(i){const el=$(`[data-touch-tools="${i}"]`);el.querySelectorAll('[data-dental-tool]').forEach(b=>b.onclick=()=>{models[i].tool=b.dataset.dentalTool;models[i].feedback=DENTAL_TOOLS.find(t=>t.id===models[i].tool).hint;el.querySelectorAll('[data-dental-tool]').forEach(x=>x.classList.toggle('selected',x===b));});el.querySelector('[data-tooth-rotate]')?.addEventListener('click',()=>{models[i].replacementAngle=models[i].replacementAngle===0?Math.PI/12:models[i].replacementAngle>0?-Math.PI/12:0;models[i].feedback='Replacement angle: '+Math.round(models[i].replacementAngle*180/Math.PI)%360+'°';});
 el.querySelectorAll('[data-ninja-mode]').forEach(b=>b.onclick=()=>{models[i].mode=b.dataset.ninjaMode;el.querySelectorAll('[data-ninja-mode]').forEach(x=>x.classList.toggle('selected',x===b));models[i].feedback={path:'Draw a glowing route around walls.',dash:'Swipe a direction, then release. One dash per swipe.',star:'Tap or drag toward a switch or guard. Costs 4 energy.',slide:'Draw a route. Slide with a smaller body for 1.7 seconds.',jump:'Start beside a wall. Drag toward a clear landing across it.',blink:'Tap or drag toward a nearby clear spot. Costs 18 energy.'}[models[i].mode];});
 const shield=el.querySelector('[data-shield]');if(shield){shield.onpointerdown=e=>{if(!playing())return;e.preventDefault();shield.setPointerCapture(e.pointerId);models[i].shield(e.pointerId,true);shield.classList.add('held');};const release=e=>{models[i].shield(e.pointerId,false);shield.classList.remove('held');};shield.onpointerup=release;shield.onpointercancel=release;shield.onlostpointercapture=release;}
 el.querySelector('[data-route-cancel]')?.addEventListener('click',()=>models[i].cancel());el.querySelector('[data-slime-split]')?.addEventListener('click',()=>{if(playing())models[i].split();});el.querySelector('[data-slime-reset]')?.addEventListener('click',()=>{if(playing())models[i].reset();});
 }
 function resize(){content.querySelectorAll('canvas').forEach(c=>prepareCanvas(c));}
 function point(c,e){const r=c.getBoundingClientRect(),scale=Math.min(r.width/1000,r.height/640),ox=(r.width-scale*1000)/2,oy=(r.height-scale*640)/2;return{x:clamp((e.clientX-r.left-ox)/scale,0,1000),y:clamp((e.clientY-r.top-oy)/scale,0,640)};}
 function bindCanvas(c,i){const own=new Set();c.onpointerdown=e=>{if(!playing()||!activeIndexes().includes(i))return;e.preventDefault();const p=point(c,e);if(models[i].input('down',p.x,p.y,e.pointerId)){own.add(e.pointerId);c.setPointerCapture(e.pointerId);}};c.onpointermove=e=>{if(!own.has(e.pointerId)||!playing())return;e.preventDefault();const p=point(c,e);models[i].input('move',p.x,p.y,e.pointerId);};const up=(e,cancel)=>{if(!own.has(e.pointerId))return;own.delete(e.pointerId);const p=point(c,e);models[i].input(cancel||!playing()?'cancel':'up',p.x,p.y,e.pointerId);if(c.hasPointerCapture(e.pointerId))c.releasePointerCapture(e.pointerId);};c.onpointerup=e=>up(e,false);c.onpointercancel=e=>up(e,true);c.onlostpointercapture=e=>up(e,true);}
 function playing(){return phase==='play'&&!paused&&page==='play';}
 function showReady(){const o=$('#touchOverlay');o.hidden=false;o.innerHTML=`<div class="result-card touch-ready"><div class="eyebrow">${versus?dentist?'EQUAL PATIENT · FRESH TOOLS':'SAME COURSE · OWN YOUR SIDE':'READY WHEN YOU ARE'}</div><h2>${dentist?esc(player(ids[turn]).name)+'’s turn.':versus?'Ready to race?':'Ready to explore?'}</h2><p>${dentist?'The timer starts when you tap Begin Treatment.':game==='slime'?'Gold orbs are required. Advanced exits also need both pads and a merged slime.':'Collect gold scrolls. Gold star switches and pressure pads open advanced exits.'}</p><button class="btn primary" id="touchBegin">${dentist?'BEGIN TREATMENT':'LET’S GO'} →</button></div>`;$('#touchBegin').onclick=beginPlaying;}
 function beginPlaying(){phase='play';paused=false;$('#touchOverlay').hidden=true;last=performance.now();audio();fx('go');}
 function pause(v){if(page!=='play'||!['play','ready','handoff'].includes(phase))return;paused=v;models.forEach(m=>m.cancel());const o=$('#touchOverlay');if(phase==='play'){o.hidden=!v;if(v){o.innerHTML='<div class="result-card"><h2>Adventure paused.</h2><p>Movement, treatments and timers are resting.</p><button class="btn primary" id="touchResume">▶ RESUME</button></div>';$('#touchResume').onclick=()=>pause(false);}$('#touchPause').textContent=v?'▶ RESUME':'Ⅱ PAUSE';}last=performance.now();}
 function hud(i){const m=models[i],p=player(ids[i]);let progress=game==='slime'?m.collected.size+'/'+m.level.orbs.length+' orbs · '+m.attempts+' retries':game==='ninja'?m.collected.size+'/'+m.level.scrolls.length+' scrolls · '+m.detected+' detections · ⚡ '+Math.ceil(m.energy):m.treated+'/'+m.total+' treated · '+m.accuracy+'% · '+m.mistakes+' mistakes';$(`[data-touch-hud="${i}"]`).innerHTML=`<span>${p.avatar} ${esc(p.name)}<small>${progress}${game==='slime'&&m.level.requiresSplit?' · '+(m.padLatched?'PADS ✓':'BOTH PADS REQUIRED'):game==='ninja'&&m.level.switch.required?' · '+(m.switchOn?'SWITCH ✓':'STAR SWITCH'):''}</small></span><strong>${m.score}<small>${seconds(m.clock)} / ${Math.round(m.duration/1000)}s</small></strong>`;
 $(`[data-touch-help="${i}"]`).textContent=m.feedback;
 if(dentist){const todo=new Map();for(const t of m.teeth)for(const k of t.tasks)if(!t.completed.has(k))todo.set(k,(todo.get(k)||0)+1);$(`[data-dental-checklist="${i}"]`).innerHTML=[...todo].map(([k,n])=>`<span>${TASK_ICONS[k]} ${k} <b>${n}</b></span>`).join('')||'<span>✨ A perfect monster smile!</span>';}
 }
 function frame(now){if(disposed)return;const dt=Math.max(0,Math.min(100,now-last));last=now;if(page==='play'){
 if(playing()){for(const i of activeIndexes())models[i].update(dt);for(const i of activeIndexes()){for(const e of models[i].events.splice(0)){if(now-notices[i]>75){fx(e==='finish'?'win':e==='oops'||e==='caught'?'bad':e==='orb'||e==='scroll'?'treasure':e==='boing'||e==='bounce'?'slime-bounce':e==='sparkle'?'dental-sparkle':'signal');notices[i]=now;}}}
 if(dentist){if(models[turn].done){if(versus&&!models[1-turn].done){phase='handoff';turn=1-turn;buildPlay();showReady();}else endRound();}}
 else if(models.some(m=>m.complete)||models.every(m=>m.done))endRound();}
 for(const i of activeIndexes()){const canvas=$(`[data-touch-canvas="${i}"]`);if(!canvas)continue;if(game==='slime')renderSlime(canvas,models[i],skins[i]);else if(game==='ninja')renderNinja(canvas,models[i],skins[i]);else renderDentist(canvas,models[i]);hud(i);}
 }raf=requestAnimationFrame(frame);}
 function entry(i){const m=models[i],d=m.summary();return{id:ids[i],score:m.score,hits:dentist?m.treated:m.collected.size,errors:dentist?m.mistakes:game==='ninja'?m.detected:m.attempts,accuracy:m.accuracy,duration:m.clock/1000,elapsed:m.clock/1000,stars:m.stars,completed:m.complete,soloWin:m.complete,details:{...d,clock:m.clock}};}
 function endRound(){if(phase!=='play')return;phase='roundresult';models.forEach(m=>m.cancel());const e=models.map((_,i)=>entry(i)),comparison=versus?(dentist?compareDentist(models[0],models[1]):compareRace(models[0],models[1])):0;if(versus&&comparison)wins[comparison>0?0:1]++;rounds.push(e);const finished=!versus||wins.some(w=>w>=Math.ceil(series/2))||round>=series;if(finished)finishMatch();else results(e,comparison,false);}
 function finishMatch(){if(committed)return;committed=true;phase='results';const entries=models.map((_,i)=>{const rows=rounds.map(r=>r[i]),last=rows.at(-1);return{...last,score:Math.round(rows.reduce((s,e)=>s+e.score,0)/rows.length),hits:rows.reduce((s,e)=>s+e.hits,0),errors:rows.reduce((s,e)=>s+e.errors,0),accuracy:Math.round(rows.reduce((s,e)=>s+e.accuracy,0)/rows.length),duration:rows.reduce((s,e)=>s+e.duration,0),details:{...last.details,rounds:rows.map(e=>e.details),series:versus?series:1,roundWins:wins[i]}};});const cmp=versus?wins[0]-wins[1]:0,winnerId=versus?cmp?ids[cmp>0?0:1]:null:undefined;recordInfo=commitRound(entries,{game,difficulty,learn:false,mode:versus?'versus':'solo',ruleset:game==='slime'?'slime-sling-v2':'touch-v1',levelId:game+'-'+level,competition:dentist?'clinic':'race',challengeKey:'series-'+(versus?series:1),winnerId,seed:level});
 entries.forEach((e,i)=>{const p=player(ids[i]),ds=e.details.rounds;for(const d of ds){if(game==='slime'){if(d.completed)unlock(p,'slime-first');if(d.stretched>=1.8)unlock(p,'slime-stretch');if(d.completed&&d.split&&d.merge)unlock(p,'slime-split');if(d.completed&&d.stars===3)unlock(p,'slime-perfect');}if(game==='dentist'){if(d.completed)unlock(p,'dentist-first');if(d.completed&&e.accuracy>=90)unlock(p,'dentist-sparkle');if(d.perfect)unlock(p,'dentist-perfect');if(d.completed&&difficulty===5)unlock(p,'dentist-expert');}if(game==='ninja'){if(d.completed)unlock(p,'ninja-first');if(d.perfect)unlock(p,'ninja-silent');if(d.perfect&&d.scrolls===models[i].level.scrolls.length)unlock(p,'ninja-perfect');if(d.completed&&d.clock<45000)unlock(p,'ninja-speed');}}
 if(versus&&winnerId===p.id)unlock(p,game==='slime'?'slime-champion':game==='dentist'?'dentist-champion':'ninja-champion');if(game==='ninja'&&completedTouchLevels(p,game)>=30)unlock(p,'ninja-master');});save();if(versus&&dentist)starter=1-starter;fx('win');results(entries,cmp,true);}
 function results(entries,cmp,finished){const o=$('#touchOverlay');o.hidden=false;o.innerHTML=`<div class="result-card wide new-celebration"><div class="eyebrow">${finished?recordInfo.some(r=>r.pb)?'✦ NEW PERSONAL BEST ✦':'PROGRESS SAVED':'ROUND '+round+' COMPLETE'}</div><h2>${versus?cmp?esc(player(ids[cmp>0?0:1]).name)+(finished?' wins!':' takes the round!'):'A brilliant tie!':entries[0].details.completed?game==='dentist'?'What a sparkling smile!':game==='slime'?'Experiment complete!':'Escape complete!':'Keep exploring!'}</h2>${versus?'<p>Match score '+wins.join(' : ')+'</p>':''}<div class="results-grid">${entries.map((e,i)=>`<section style="--player:${player(ids[i]).color}"><span class="avatar">${player(ids[i]).avatar}</span><h3>${esc(player(ids[i]).name)}</h3><div class="big-score">${e.score}<small>${versus&&series>1?'AVG POINTS / ROUND':'POINTS'}</small></div><p>${e.details.completed?'★'.repeat(e.stars||1)+' Completed':'Challenge in progress'}<br>${dentist?e.hits+' treatments':e.hits+(game==='slime'?' orbs':' scrolls')} · ${e.accuracy}% accuracy<br>${seconds(e.duration*1000)} active time · ${e.errors} ${dentist?'mistakes':game==='slime'?'retries':'detections'}</p></section>`).join('')}</div><div class="modal-actions"><button class="btn secondary" id="touchResultHome">ARCADE</button><button class="btn secondary" id="touchResultSetup">SETUP</button>${finished?`<button class="btn secondary" id="touchResultRecords">RECORDS</button>${!versus&&entries[0].details.completed&&level<30?'<button class="btn accent" id="touchNextLevel">NEXT →</button>':''}<button class="btn primary" id="touchRematch">${versus?'REMATCH':'PLAY AGAIN'} ↻</button>`:'<button class="btn primary" id="touchNextRound">NEXT ROUND →</button>'}</div></div>`;$('#touchResultHome').onclick=exit;$('#touchResultSetup').onclick=setup;if(finished){$('#touchResultRecords').onclick=records;$('#touchRematch').onclick=()=>{round=0;rounds=[];wins=[0,0];committed=false;requestSession();};if($('#touchNextLevel'))$('#touchNextLevel').onclick=()=>{level++;difficulty=Math.floor((level-1)/6)+1;round=0;rounds=[];wins=[0,0];committed=false;requestSession();};}else $('#touchNextRound').onclick=startRound;}
 function records(){page='records';phase='setup';models=[];observer.disconnect();const rows=DB.profiles.flatMap(p=>p.results.filter(r=>r.game===game&&r.ruleset===(game==='slime'?'slime-sling-v2':'touch-v1')&&r.difficulty===difficulty&&r.levelId===game+'-'+level&&r.mode===(versus?'versus':'solo')&&r.challengeKey==='series-'+(versus?series:1)).map(r=>({p,r}))).sort((a,b)=>b.r.score-a.r.score||a.r.duration-b.r.duration);content.innerHTML=`<div class="new-records"><div class="page-heading"><div><span class="eyebrow">REAL PLAYERS · REAL PROGRESS</span><h2>${spec.name} records.</h2><p>${LEVELS[difficulty-1]} · ${dentist?'case':'level'} ${level} · ${versus?'best of '+series:'solo'}. Each level, difficulty and match length has separate records.</p></div><button class="btn primary" id="touchRecordsPlay">PLAY →</button></div><div class="touch-record-filters"><label>Level<select id="touchRecordLevel">${Array.from({length:30},(_,i)=>`<option value="${i+1}" ${i+1===level?'selected':''}>${i+1} · ${levelName(i+1)}</option>`).join('')}</select></label><label>Players<select id="touchRecordMode"><option value="solo" ${!versus?'selected':''}>Solo</option><option value="versus" ${versus?'selected':''}>2 players</option></select></label>${versus?`<label>Match<select id="touchRecordSeries">${[1,3,5].map(n=>`<option value="${n}" ${series===n?'selected':''}>Best of ${n}</option>`).join('')}</select></label>`:''}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>PLAYER</th><th>SCORE</th><th>${dentist?'TREATMENTS':game==='slime'?'ORBS':'SCROLLS'}</th><th>ACCURACY</th><th>TIME</th><th>${dentist?'MISTAKES':game==='slime'?'RETRIES':'DETECTIONS'}</th></tr></thead><tbody>${rows.map(({p,r})=>`<tr><td>${p.avatar} ${esc(p.name)}</td><td>${r.score}</td><td>${r.hits}</td><td>${r.accuracy}%</td><td>${r.duration.toFixed(1)}s</td><td>${r.errors}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><h2>A fresh adventure.</h2><p>Complete a challenge in this exact mode to save your record here.</p></div>'}<div class="touch-record-summary">${DB.profiles.map(p=>{const rs=p.results.filter(r=>r.game===game),ds=rs.flatMap(r=>r.details?.rounds||[r.details]).filter(Boolean),full=ds.filter(d=>d.completed);return `<article class="panel"><span class="avatar" style="--player:${p.color}">${p.avatar}</span><h3>${esc(p.name)}</h3><p>${dentist?full.length+' patients treated':completedTouchLevels(p,game)+' levels completed'}<br>${ds.filter(d=>d.perfect||d.stars===3).length} perfect finishes<br>${rs.filter(r=>r.mode==='versus'&&r.win).length} multiplayer wins<br>Fastest full finish: ${full.length?seconds(Math.min(...full.map(d=>d.clock))):'—'}</p></article>`;}).join('')}</div></div>`;
 $('#touchRecordsPlay').onclick=setup;$('#touchRecordLevel').onchange=e=>{level=+e.target.value;difficulty=Math.floor((level-1)/6)+1;records();};$('#touchRecordMode').onchange=e=>{versus=e.target.value==='versus';records();};if($('#touchRecordSeries'))$('#touchRecordSeries').onchange=e=>{series=+e.target.value;records();};
 }
 function visibility(){if(document.hidden)pause(true);}document.addEventListener('visibilitychange',visibility);if(initialPage==='records')records();else setup();raf=requestAnimationFrame(frame);
 return()=>{disposed=true;gate.dispose();cancelAnimationFrame(raf);observer.disconnect();models.forEach(m=>m.cancel());document.removeEventListener('visibilitychange',visibility);};
}
